const shadowRoot = this.attachShadow({ mode: "open" });

// Load styles in the shadowRoot so we don't leak it.
const style = document.createElement("link");
style.rel = "stylesheet";
style.href = "chrome://messenger/skin/calendar/calendarDialogRow.css";

const template = document.getElementById("calendarDialogRowTemplate");
const clonedNode = template.content.cloneNode(true);
shadowRoot.append(clonedNode, style);

add_task(function test_slotElements() {
  const labelSlotElement = row.shadowRoot
    .querySelector('slot[name="label"]')
    .assignedElements()[0];
  Assert.equal(
    labelSlotElement,
    row.querySelector('[slot="label"]'),
    "Text label should be in label slot"
  );

  const contentSlotElement = row.shadowRoot
    .querySelector('slot[name="content"]')
    .assignedElements()[0];
